from docx import Document
p='/mnt/data/GMRI_GEV_Proxmox9_LXC_Deployment_PRD_v1.1.docx'
d=Document(p)
for i,para in enumerate(d.paragraphs):
    t=para.text.strip()
    if t:
        print(f'{i}: {t}')
for ti,table in enumerate(d.tables):
    print(f'\n[TABLE {ti}]')
    for row in table.rows:
        print(' | '.join(c.text.replace('\n',' / ') for c in row.cells))
PY

bash -lc python - <<'PY'
from docx import Document
p='/mnt/data/GMRI_GEV_Proxmox9_LXC_Deployment_PRD_v1.2.docx'
d=Document(p)
for sec in d.sections:
    for f in [sec.footer, sec.first_page_footer, sec.even_page_footer]:
        for para in f.paragraphs:
            if 'PRD v1.1' in para.text:
                for run in para.runs:
                    if 'PRD v1.1' in run.text:
                        run.text=run.text.replace('PRD v1.1','PRD v1.2')
                if 'PRD v1.1' in para.text:
                    # fallback reset if split across runs
                    txt=para.text.replace('PRD v1.1','PRD v1.2')
                    for r in list(para.runs): para._p.remove(r._r)
                    para.add_run(txt)
d.save(p)
PY
